def solve(g, mode='overwrite'):
    Hn,Wn=len(g),len(g[0])
    claims={}
    comps=components(g)
    for col,cells in comps:
        if len(cells)==9:
            rs=[a for a,_ in cells]; cs=[b for _,b in cells]
            cr=sum(rs)//9; ccl=sum(cs)//9
            for j in range(Wn): claims.setdefault((cr,j,set()))[0] if False else None
    # redo cleanly
    lines=[]
    for col,cells in comps:
        if len(cells)==9:
            rs=[a for a,_ in cells]; cs=[b for _,b in cells]
            lines.append((col,sum(rs)//9,sum(cs)//9))
    out=[r[:] for r in g]
    for r in range(Hn):
        for c in range(Wn):
            hits=[col for col,cr,cc in lines if r==cr or c==cc]
            if len(hits)>1: out[r][c]=0
            elif len(hits)==1:
                if mode=='overwrite': out[r][c]=hits[0]
                elif mode=='preserve': out[r][c]=g[r][c] if g[r][c] else hits[0]
                elif mode=='erase': out[r][c]=0 if g[r][c] else hits[0]
    return out
